class Solution:
    def countTargetStretches(self, nums: List[int], target: int) -> int:
        n, count = len(nums), 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                if s == target:
                    count += 1
        return count

