from collections import Counter

class Solution:
    def countTargetStretches(self, nums: List[int], target: int) -> int:
        seen = Counter({0: 1})
        count = prefix = 0
        for x in nums:
            prefix += x
            count += seen[prefix - target]
            seen[prefix] += 1
        return count

