class Solution {
    public long countTargetStretches(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        long count = 0;
        int prefix = 0;
        for (int x : nums) {
            prefix += x;
            count += seen.getOrDefault(prefix - target, 0);
            seen.merge(prefix, 1, Integer::sum);
        }
        return count;
    }
}

