class Solution {
public:
    long long countTargetStretches(vector<int>& nums, int target) {
        unordered_map<int, int> seen{{0, 1}};
        long long count = 0;
        int prefix = 0;
        for (int x : nums) {
            prefix += x;
            auto it = seen.find(prefix - target);
            if (it != seen.end()) count += it->second;
            seen[prefix]++;
        }
        return count;
    }
};

