// A small hash map from a prefix sum to how many times it occurred.
typedef struct { int key; int count; bool used; } Slot;

static Slot* slotFor(Slot* t, unsigned mask, int key) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    unsigned s = (unsigned) (h >> 32) & mask;
    while (t[s].used && t[s].key != key) s = (s + 1) & mask;
    return &t[s];
}

long long countTargetStretches(int* nums, int numsSize, int target) {
    unsigned cap = 1;
    while (cap < 2u * (numsSize + 1)) cap <<= 1;
    Slot* seen = calloc(cap, sizeof(Slot));
    Slot* zero = slotFor(seen, cap - 1, 0);
    *zero = (Slot) {0, 1, true};
    long long count = 0;
    int prefix = 0;
    for (int i = 0; i < numsSize; i++) {
        prefix += nums[i];
        Slot* want = slotFor(seen, cap - 1, prefix - target);
        if (want->used) count += want->count;
        Slot* mine = slotFor(seen, cap - 1, prefix);
        mine->key = prefix;
        mine->used = true;
        mine->count++;
    }
    free(seen);
    return count;
}
